// vCAOC JCEOI: per-theater frequency registers (DCS in-game + real-world), the standard Blue net plan and the
// clear-channel pool. Data comes from js/jceoi-data.js, generated by tools/jceoi/build.py -- edit the sources there.
(function () {
  const J = window.AOC_JCEOI;
  const bandOf = f => f >= 2 && f < 30 ? "HF" : f >= 30 && f < 88 ? "VHF-FM" : f >= 108 && f < 118 ? "VHF-NAV" : f >= 118 && f < 156 ? "VHF-AM"
    : f >= 156 && f < 174 ? "VHF-MAR" : f >= 225 && f < 400 ? "UHF" : f < 2 ? "LF/MF" : "OTHER";
  // a VHF-AM net also has to clear VOR/ILS in 108-118 MHz (DCS VHF radios tune from 116 MHz)
  const sameBand = (a, b) => a === b || (a === "VHF-AM" && b === "VHF-NAV");
  const cols = J.regCols;
  const rows = {};
  J.theaters.forEach(t => { rows[t.key] = t.register.map(r => { const o = Object.fromEntries(cols.map((c, i) => [c, r[i]])); o.band = bandOf(o.mhz); o.theater = t.key; return o; }); });
  // campaign theater names (proposal form) -> JCEOI theater keys
  const ALIAS = { "Marianas": "Marianas", "Mariana Islands": "Marianas", "Germany (Cold War)": "Germany (Cold War)", "Germany": "Germany (Cold War)",
    "Persian Gulf": "Persian Gulf", "Caucasus": "Caucasus", "Syria": "Syria", "Nevada": "Nevada", "Sinai": "Sinai", "Kola": "Kola",
    "Afghanistan": "Afghanistan", "Iraq": "Iraq", "Falklands": "Falklands", "South Atlantic": "Falklands", "Balkans": "Balkans" };
  const theaterKey = name => ALIAS[name] || (rows[name] ? name : null);
  const register = key => key ? rows[key] || [] : Object.values(rows).flat();
  const fmt = f => f == null ? "" : bandOf(f) === "HF" ? f.toFixed(3) : f.toFixed(3);

  // everything documented within one channel of f: the theater's register (or all theaters) and the common list
  function conflicts(f, key) {
    f = +f; if (!isFinite(f)) return [];
    const b = bandOf(f), sep = (J.sep[b] || 0.025) - 1e-9, out = [];
    if (Math.abs(f - 121.5) < J.guardZone || Math.abs(f - 243.0) < J.guardZone)
      out.push({ site: "Guard", use: `within ${J.guardZone * 1000} kHz of ${Math.abs(f - 121.5) < 1 ? "121.500" : "243.000"} Guard`, mhz: Math.abs(f - 121.5) < 1 ? 121.5 : 243.0, kind: "guard", src: "JCEOI rule", conf: "official", theater: "all" });
    register(key).forEach(e => { if (sameBand(b, e.band) && Math.abs(e.mhz - f) < sep) out.push(e); });
    J.common.forEach(c => { if (sameBand(b, c.band) && Math.abs(c.mhz - f) < sep) out.push({ site: "Common / standard", use: c.use, mhz: c.mhz, kind: "common", src: c.src, conf: c.conf, theater: "all" }); });
    return out;
  }
  // clear channels in a band (or a sub-range) for one theater, or for every theater at once
  function pool(key, band, lo, hi) {
    const [blo, bhi, step] = J.bands[band], a = Math.ceil(((lo ?? blo) - 1e-9) / step), z = Math.floor(((hi ?? bhi) + 1e-9) / step);
    const sep = J.sep[band] - 1e-9, docs = [...register(key), ...J.common.map(c => ({ ...c }))].filter(e => sameBand(band, e.band)).map(e => e.mhz).sort((x, y) => x - y);
    const plan = new Set(J.nets.flatMap(n => [n.uhf, n.uhfAlt, n.vhf, n.fm, n.hf]).filter(x => x != null).map(x => x.toFixed(3)));
    const out = [];
    for (let i = a, j = 0; i <= z; i++) {
      const f = +(i * step).toFixed(3);
      if (Math.abs(f - 121.5) < J.guardZone || Math.abs(f - 243.0) < J.guardZone) continue;
      while (j < docs.length && docs[j] < f - sep) j++;
      if (j < docs.length && Math.abs(docs[j] - f) < sep) continue;
      out.push({ mhz: f, inPlan: plan.has(f.toFixed(3)) });
    }
    return out;
  }
  // the standard net for a Comm Plan matrix channel id ("WHITE 1")
  const net = id => J.nets.find(n => n.id === id);
  // the data must have been built from the Comm Plan (ACP) template this page has; if not, the net plan is stale
  const inSync = JSON.stringify(J.template) === JSON.stringify(window.AOC.COMM?.TEMPLATE);
  if (!inSync) console.warn("JCEOI data was built from a different Comm Plan template — run tools/jceoi/build.py");

  window.AOC.JCEOI = { data: J, inSync, bandOf, theaterKey, register, conflicts, pool, net, fmt, theaters: J.theaters.map(t => ({ key: t.key, status: t.status, dcs: t.dcs, count: t.register.length, tacan: t.tacan })) };
})();
